// Sektör eşleme
const categoryToSector: Record<CategoryKey, string> = {
  "ai-automation": "teknoloji",
  content: "pazarlama",
  consulting: "is-yonetimi",
  "customer-success": "satis",
  design: "tasarim",
  development: "teknoloji",
  ecommerce: "satis",
  email: "pazarlama",
  finance: "is-yonetimi",
  marketing: "pazarlama",
  product: "is-yonetimi",
  productivity: "kisisel-gelisim",
  sales: "satis",
  seo: "pazarlama",
  "social-media": "pazarlama",
  startup: "girisimcilik",
  saas: "teknoloji",
};

function buildSkills(): Skill[] {
  const skills: Skill[] = [];

  for (const [category, defs] of Object.entries(categorySkills)) {
    const cat = category as CategoryKey;
    const source = cat === "saas" ? "tezgah" : "kalfa";

    for (const [id, name, description, importance, tags] of defs) {
      skills.push({
        id: `${cat}--${id}`,
        name,
        description,
        category: cat,
        sector: categoryToSector[cat] as any,
        importance,
        source: source as any,
        tags,
        slug: id,
        filePath: `/skills/${cat}/${id}/SKILL.md`,
      });
    }
  }

  return skills;
}

export const skills: Skill[] = buildSkills();
